ALTER TABLE `finance` ADD `iban_control` decimal(26,0) default NULL;
UPDATE `finance` SET `iban_control` = CONCAT(`bank_account`, '142800') WHERE LENGTH(`bank_account`) = 20 AND `bank_account` REGEXP('^[0-9]');
UPDATE `finance` SET `iban_control` = `iban_control` % 97 WHERE `iban_control` IS NOT NULL;
UPDATE `finance` SET `iban_control` = 98 - `iban_control` WHERE `iban_control` IS NOT NULL;
UPDATE `finance` SET `iban_control` = 0 WHERE `bank_account` IS NOT NULL AND `iban_control` IS NULL;
UPDATE `finance` SET `bank_account` = CONCAT('ES', LPAD(`iban_control`, 2, '0'), `bank_account`) WHERE `iban_control` IS NOT NULL;
ALTER TABLE `finance` DROP `iban_control`;

